<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'

const router = useRouter()
const activeGesture = ref('Hello')
const isDemoRunning = ref(true)
const mobileMenuOpen = ref(false)
const demoTick = ref(0)
let demoTimer

const gestures = [
  { name: 'Hello', translation: 'Xin chào', confidence: 91, color: 'cyan', note: 'Open palm detected' },
  { name: 'Thank you', translation: 'Cảm ơn', confidence: 96, color: 'violet', note: 'Forward motion detected' },
  { name: 'Yes', translation: 'Có', confidence: 94, color: 'pink', note: 'Vertical nod detected' },
  { name: 'No', translation: 'Không', confidence: 89, color: 'blue', note: 'Lateral motion detected' }
]

const selectedGesture = computed(() => gestures.find((gesture) => gesture.name === activeGesture.value) || gestures[0])
const liveConfidence = computed(() => Math.min(99, selectedGesture.value.confidence + (demoTick.value % 3) - 1))
const latency = computed(() => 42 + (demoTick.value % 4))

const selectGesture = (gesture) => {
  activeGesture.value = gesture.name
  isDemoRunning.value = true
}

const toggleDemo = () => {
  isDemoRunning.value = !isDemoRunning.value
}

const openPlayground = () => {
  router.push('/realtime-ai-playground')
}

const scrollTo = (id) => {
  mobileMenuOpen.value = false
  document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' })
}

onMounted(() => {
  demoTimer = window.setInterval(() => {
    if (isDemoRunning.value) demoTick.value += 1
  }, 1400)
})

onBeforeUnmount(() => window.clearInterval(demoTimer))
</script>

